/bin/bash -lc "python3 - <<'PY'
import json,os
p=os.path.join(os.environ['TMPDIR'],'bbau_result.json'); d=json.load(open(p))
N={
'ba_history':(70,'ba_history','Social Sciences & Education > BA History'),
'bsc_physics':(24,'bsc_physics','Common Paths > B.Sc Physics'),
'art_law':(347,'art_law','Law & Civil Services'),
'art_social':(348,'art_social','Social Sciences & Education')}
def mp(k,r,c='medium'):
 i,s,b=N[k]
 return {'career_node_id':i,'career_node_slug':s,'career_breadcrumb':b,'relation':r,'confidence':c,'mapping_status':'reviewed_with_career_tree_label_issue'}
for c in d['courses']:
 n=c['name']
 if n in ['Ph.D - Human Development and Family Studies','M.Sc. (Human Development and Family Studies)','M.A. (Development Study)','Ph.D. Development Studies']:
  c['career_path_mappings']=[mp('art_social','nearest parent: social sciences and education')]; c['mapping_gap']=None
 elif n=='Ph.D - Law':
  c['career_path_mappings']=[mp('art_law','nearest parent: law and civil services')]; c['mapping_gap']=None
 elif n=='MA':
  c['career_path_mappings']=[mp('ba_history','closest specialization: history')]; c['mapping_gap']=None
 elif n=='M.Sc. (Nuclear Medicine Technology)':
  c['career_path_mappings']=[mp('bsc_physics','closest specialization: physics/nuclear medicine','low')]; c['mapping_gap']=None
open(p,'w').write(json.dumps(d,ensure_ascii=False,separators=(',',':')))
print('unmapped',sum(not c['career_path_mappings'] for c in d['courses']))
for c in d['courses']:
 if not c['career_path_mappings']: print(c['course_id'],c['name'])
PY
jq -e 'type==\"object\" and .record_status==\"manual_review\" and .course_catalogue_status==\"partial_official_website\"' \""'$TMPDIR/bbau_result.json"'

